            "case": case["case_id"], "supplier": sid, "round": len(p["rounds"]), "status_in": status,
            "sheets": sheets, "c_sheets": [economics.cost(case, s, p["std"], p["est"]) for s in sheets],
            "claims": sorted(ids), "move": move, "llm": used_llm, "latency_s": p["rounds"][-1]["latency_s"],
            "mood": reading.get("mood"), "themes": p["themes"],
        })
